	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a LancamentoFinanceiro
	var b Titulo

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, lancamentoFinanceiroDBTypes, false, strmangle.SetComplement(lancamentoFinanceiroPrimaryKeyColumns, lancamentoFinanceiroColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &b, tituloDBTypes, false, strmangle.SetComplement(tituloPrimaryKeyColumns, tituloColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}

	if err = a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	if err = a.SetTit(ctx, tx, true, &b); err != nil {
		t.Fatal(err)
	}

	if err = a.RemoveTit(ctx, tx, &b); err != nil {
		t.Error("failed to remove relationship")
	}

	count, err := a.Tit().Count(ctx, tx)
	if err != nil {
		t.Error(err)
	}
	if count != 0 {
		t.Error("want no relationships remaining")
	}

